  1→import { useState, useMemo, useRef, useEffect } from "react";
  2→import { cn } from "@/lib/utils";
  3→import { Plus, Clock, Loader2, Briefcase, Search, MoreHorizontal, Pencil, Trash2, FileText } from "lucide-react";
  4→import { format } from "date-fns";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { SidebarInput } from "@/components/ui/sidebar";
  8→import { supabase } from "@/integrations/supabase/client";
  9→import { toast } from "sonner";
 10→import {
 11→  DropdownMenu,
 12→  DropdownMenuContent,
 13→  DropdownMenuItem,
 14→  DropdownMenuTrigger,
 15→} from "@/components/ui/dropdown-menu";
 16→import {
 17→  AlertDialog,
 18→  AlertDialogAction,
 19→  AlertDialogCancel,
 20→  AlertDialogContent,
 21→  AlertDialogDescription,
 22→  AlertDialogFooter,
 23→  AlertDialogHeader,
 24→  AlertDialogTitle,
 25→} from "@/components/ui/alert-dialog";
 26→import {
 27→  Sidebar,
 28→  SidebarContent,
 29→  SidebarHeader,
 30→  SidebarGroup,
 31→  SidebarGroupLabel,
 32→  SidebarGroupContent,
 33→  SidebarMenu,
 34→  SidebarMenuItem,
 35→  SidebarMenuButton,
 36→} from "@/components/ui/sidebar";
 37→
 38→interface PastJob {
 39→  id: string;
 40→  title: string | null;
 41→  job_description: string;
 42→  status: string;
 43→  created_at: string;
 44→  resume_count: number;
 45→}
 46→
 47→interface JobSidebarProps {
 48→  pastJobs: PastJob[];
 49→  selectedJobId: string | null;
 50→  loadingPastJobs: boolean;
 51→  onSelectJob: (jobId: string) => void;
 52→  onNewJob: () => void;
 53→  onRenameJob: (jobId: string, newTitle: string) => void;
 54→  onDeleteJob: (jobId: string) => void;
 55→  onAuthRequired?: () => void;
 56→  isAuthenticated?: boolean;
 57→}
 58→
 59→function getDisplayTitle(job: PastJob): string {
 60→  if (job.title) return job.title;
 61→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 62→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 63→}
 64→
 65→const JobSidebar = ({ pastJobs, selectedJobId, loadingPastJobs, onSelectJob, onNewJob, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
 66→  const [search, setSearch] = useState("");
 67→  const [editingId, setEditingId] = useState<string | null>(null);
 68→  const [editValue, setEditValue] = useState("");
 69→  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
 70→  const editInputRef = useRef<HTMLInputElement>(null);
 71→
 72→  const filteredJobs = useMemo(() => {
 73→    if (!search.trim()) return pastJobs;
 74→    const q = search.toLowerCase();
 75→    return pastJobs.filter(
 76→      (job) =>
 77→        getDisplayTitle(job).toLowerCase().includes(q) ||
 78→        job.job_description.toLowerCase().includes(q)
 79→    );
 80→  }, [pastJobs, search]);
 81→
 82→  useEffect(() => {
 83→    if (editingId && editInputRef.current) {
 84→      editInputRef.current.focus();
 85→      editInputRef.current.select();
 86→    }
 87→  }, [editingId]);
 88→
 89→  const startEditing = (job: PastJob) => {
 90→    setEditingId(job.id);
 91→    setEditValue(getDisplayTitle(job));
 92→  };
 93→
 94→  const saveRename = async () => {
 95→    if (!editingId || !editValue.trim()) {
 96→      setEditingId(null);
 97→      return;
 98→    }
 99→    try {
100→      const { error } = await supabase
101→        .from("jobs")
102→        .update({ title: editValue.trim() } as any)
103→        .eq("id", editingId);
104→      if (error) throw error;
105→      onRenameJob(editingId, editValue.trim());
106→      toast.success("Job renamed");
107→    } catch {
108→      toast.error("Failed to rename job");
109→    }
110→    setEditingId(null);
111→  };
112→
113→  const cancelEditing = () => setEditingId(null);
114→
115→  const confirmDelete = () => {
116→    if (deleteJobId) {
117→      onDeleteJob(deleteJobId);
118→      setDeleteJobId(null);
119→    }
120→  };
121→
122→  return (
123→    <>
124→      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
125→        <SidebarHeader className="p-4 space-y-3">
126→          <Button onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }} className="w-full gap-2" size="sm">
127→            <Plus className="h-4 w-4" />
128→            New Job
129→          </Button>
130→          <div className="relative">
131→            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
132→            <SidebarInput
133→              placeholder="Search jobs…"
134→              value={search}
135→              onChange={(e) => setSearch(e.target.value)}
136→              className="pl-8"
137→            />
138→          </div>
139→        </SidebarHeader>
140→
141→        <SidebarContent>
142→          <SidebarGroup>
143→            <SidebarGroupLabel className="px-4 flex items-center gap-2">
144→              <Briefcase className="h-4 w-4" />
145→              <span>Job History</span>
146→              {search && <span className="ml-auto text-[10px]">({filteredJobs.length})</span>}
147→            </SidebarGroupLabel>
148→            <SidebarGroupContent>
149→              {!isAuthenticated ? (
150→                <div className="px-3 py-3">
151→                  <button
152→                    onClick={() => onAuthRequired?.()}
153→                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
154→                  >
155→                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
156→                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
157→                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
158→                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
159→                      Sign in to get started →
160→                    </span>
161→                  </button>
162→                </div>
163→              ) : loadingPastJobs ? (
164→                <div className="flex items-center justify-center py-8">
165→                  <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
166→                </div>
167→              ) : filteredJobs.length === 0 ? (
168→                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
169→                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
170→                </p>
171→              ) : (
172→                <SidebarMenu className="space-y-1.5 px-2">
173→                  {filteredJobs.map((job) => (
174→                    <SidebarMenuItem key={job.id}>
175→                      {editingId === job.id ? (
176→                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
177→                          <Input
178→                            ref={editInputRef}
179→                            value={editValue}
180→                            onChange={(e) => setEditValue(e.target.value)}
181→                            onKeyDown={(e) => {
182→                              if (e.key === "Enter") saveRename();
183→                              if (e.key === "Escape") cancelEditing();
184→                            }}
185→                            onBlur={saveRename}
186→                            className="h-7 text-sm"
187→                          />
188→                        </div>
189→                      ) : (
190→                        <SidebarMenuButton
191→                          isActive={selectedJobId === job.id}
192→                          onClick={() => onSelectJob(job.id)}
193→                          className={cn(
194→                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
195→                            "rounded-lg border transition-colors",
196→                            selectedJobId === job.id
197→                              ? "border-l-2 border-l-primary bg-sidebar-accent"
198→                              : "border-transparent hover:bg-sidebar-accent/50"
199→                          )}
200→                        >
201→                          <div className="flex items-center gap-1 w-full">
202→                            <span className="text-sm leading-snug line-clamp-2 flex-1">
203→                              {getDisplayTitle(job)}
204→                            </span>
205→                            <DropdownMenu>
206→                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
207→                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
208→                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
209→                                </button>
210→                              </DropdownMenuTrigger>
211→                              <DropdownMenuContent align="end" className="w-36">
212→                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
213→                                  <Pencil className="h-3.5 w-3.5 mr-2" />
214→                                  Rename
215→                                </DropdownMenuItem>
216→                                <DropdownMenuItem
217→                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
218→                                  className="text-destructive focus:text-destructive"
219→                                >
220→                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
221→                                  Delete
222→                                </DropdownMenuItem>
223→                              </DropdownMenuContent>
224→                            </DropdownMenu>
225→                          </div>
226→                          <div className="flex items-center gap-2 w-full">
227→                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
228→                              <FileText className="h-2.5 w-2.5" />
229→                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
230→                            </span>
231→                            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5 ml-auto">
232→                              <Clock className="h-2.5 w-2.5" />
233→                              {format(new Date(job.created_at), "MMM d, yyyy")}
234→                            </span>
235→                          </div>
236→                        </SidebarMenuButton>
237→                      )}
238→                    </SidebarMenuItem>
239→                  ))}
240→                </SidebarMenu>
241→              )}
242→            </SidebarGroupContent>
243→          </SidebarGroup>
244→        </SidebarContent>
245→      </Sidebar>
246→
247→      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
248→        <AlertDialogContent>
249→          <AlertDialogHeader>
250→            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
251→            <AlertDialogDescription>
252→              This will permanently delete this job and all its resumes. This action cannot be undone.
253→            </AlertDialogDescription>
254→          </AlertDialogHeader>
255→          <AlertDialogFooter>
256→            <AlertDialogCancel>Cancel</AlertDialogCancel>
257→            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
258→              Delete
259→            </AlertDialogAction>
260→          </AlertDialogFooter>
261→        </AlertDialogContent>
262→      </AlertDialog>
263→    </>
264→  );
265→};
266→
267→export default JobSidebar;
268→

  1→import { useState, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { Card, CardContent } from "@/components/ui/card";
  4→import { Button } from "@/components/ui/button";
  5→import { Badge } from "@/components/ui/badge";
  6→import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
  7→import { User, ShoppingCart, Crown, Zap, ArrowUpRight, AlertTriangle } from "lucide-react";
  8→import BuyCreditsDialog from "@/components/BuyCreditsDialog";
  9→import SubscriptionDialog from "@/components/SubscriptionDialog";
 10→import { useNavigate } from "react-router-dom";
 11→
 12→type CreditType = { key: string; color: string; label: string; count: number; desc: string };
 13→
 14→const CREDIT_TYPES: Omit<CreditType, "count">[] = [
 15→  { key: "monthly", color: "hsl(var(--rk-primary))", label: "Monthly", desc: "From your subscription — consumed first." },
 16→  { key: "topup", color: "hsl(var(--rk-score-overall))", label: "Top-up", desc: "One-time pack purchase — never expire, used after monthly." },
 17→  { key: "bonus", color: "hsl(var(--rk-score-education))", label: "Bonus", desc: "Bonus credits — used last, never expire." },
 18→];
 19→
 20→const AccountInfoCard = () => {
 21→  const { user, profile } = useAuth();
 22→  const navigate = useNavigate();
 23→  const [animated, setAnimated] = useState(false);
 24→
 25→  useEffect(() => {
 26→    const t = setTimeout(() => setAnimated(true), 50);
 27→    return () => clearTimeout(t);
 28→  }, []);
 29→
 30→  const subCredits = profile?.subscription_credits ?? 0;
 31→  const topCredits = profile?.topup_credits ?? 0;
 32→  const bonusCredits = profile?.bonus_credits ?? 0;
 33→  const splitTotal = subCredits + topCredits + bonusCredits;
 34→  const legacyCredits = profile?.credits ?? 0;
 35→  const total = splitTotal > 0 ? splitTotal : legacyCredits;
 36→  const showLegacy = splitTotal === 0 && legacyCredits > 0;
 37→
 38→  const plan = profile?.plan ?? "free";
 39→  const isPaid = plan !== "free";
 40→  const isLow = total < 3;
 41→
 42→  // Build credit types with counts
 43→  const creditTypes: CreditType[] = showLegacy
 44→    ? [{ key: "legacy", color: "hsl(var(--rk-primary))", label: "Available", count: legacyCredits, desc: "Your available credits." }]
 45→    : CREDIT_TYPES.map((t) => ({
 46→        ...t,
 47→        count: t.key === "monthly" ? subCredits : t.key === "topup" ? topCredits : bonusCredits,
 48→      }));
 49→
 50→  const activeSegments = creditTypes.filter((t) => t.count > 0);
 51→  const activeSource = subCredits > 0 ? "monthly" : topCredits > 0 ? "top-up" : bonusCredits > 0 ? "bonus" : null;
 52→
 53→
 54→  return (
 55→    <Card className="overflow-hidden">
 56→      {/* Hero banner */}
 57→      <div className="relative bg-gradient-to-br from-primary/10 via-primary/5 to-transparent dark:from-primary/20 dark:via-primary/10 px-6 pt-6 pb-8">
 58→        <div className="flex items-start justify-between">
 59→          <div className="flex items-center gap-3">
 60→            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 ring-2 ring-primary/20">
 61→              <User className="h-6 w-6 text-primary" />
 62→            </div>
 63→            <div>
 64→              <p className="text-sm font-medium text-muted-foreground">Welcome back</p>
 65→              <p className="text-base font-semibold text-foreground truncate max-w-[220px] sm:max-w-none">
 66→                {user?.email}
 67→              </p>
 68→            </div>
 69→          </div>
 70→          <div className="flex items-center gap-2">
 71→            <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
 72→              {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
 73→              {isPaid ? plan : "Pay As You Go"}
 74→            </Badge>
 75→            <SubscriptionDialog
 76→              trigger={
 77→                <Button variant="ghost" size="sm" className="h-7 gap-1 text-xs text-primary hover:text-primary">
 78→                  <ArrowUpRight className="h-3 w-3" />
 79→                  {isPaid ? "Manage" : "Upgrade"}
 80→                </Button>
 81→              }
 82→            />
 83→          </div>
 84→        </div>
 85→      </div>
 86→
 87→      {/* Credits section */}
 88→      <CardContent className="px-6 py-5 space-y-3">
 89→        {/* Header row */}
 90→        <div className="flex items-center justify-between">
 91→          <span className="text-sm font-semibold text-foreground">Credits</span>
 92→          <div className="flex items-center gap-3">
 93→            <span className="text-sm font-semibold text-foreground tabular-nums">
 94→              {total}
 95→              <span className="text-muted-foreground font-normal ml-1">left</span>
 96→            </span>
 97→            <BuyCreditsDialog
 98→              trigger={
 99→                <Button size="sm" variant="outline" className="h-7 gap-1.5 text-xs">
100→                  <ShoppingCart className="h-3 w-3" />
101→                  Buy
102→                </Button>
103→              }
104→            />
105→          </div>
106→        </div>
107→
108→        {/* Segmented bar */}
109→        <TooltipProvider delayDuration={80}>
110→          <div className="space-y-2">
111→            {/* Bar track */}
112→            <div className="relative h-2 w-full rounded-full bg-muted">
113→              <div className="absolute inset-0 flex gap-[2px]">
114→                {activeSegments.map((seg, i) => {
115→                  const pct = (seg.count / total) * 100;
116→                  return (
117→                    <Tooltip key={seg.key}>
118→                      <TooltipTrigger asChild>
119→                        <div
120→                          className="h-full cursor-pointer transition-all duration-500 ease-out hover:brightness-110"
121→                          style={{
122→                            width: animated ? `${pct}%` : "0%",
123→                            backgroundColor: seg.color,
124→                            transitionDelay: `${i * 100}ms`,
125→                            borderRadius:
126→                              activeSegments.length === 1
127→                                ? "9999px"
128→                                : i === 0
129→                                ? "9999px 0 0 9999px"
130→                                : i === activeSegments.length - 1
131→                                ? "0 9999px 9999px 0"
132→                                : "0",
133→                          }}
134→                        />
135→                      </TooltipTrigger>
136→                      <TooltipContent side="top" className="max-w-[220px] p-3 space-y-1">
137→                        <div className="flex items-center gap-2">
138→                          <span className="inline-block w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: seg.color }} />
139→                          <span className="font-semibold text-sm">{seg.label}</span>
140→                        </div>
141→                        <p className="text-base font-bold tabular-nums">{seg.count} credits</p>
142→                        <p className="text-xs text-muted-foreground leading-relaxed">{seg.desc}</p>
143→                      </TooltipContent>
144→                    </Tooltip>
145→                  );
146→                })}
147→              </div>
148→            </div>
149→
150→            {/* Always-visible legend */}
151→            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
152→              {creditTypes.map((ct) => (
153→                <span
154→                  key={ct.key}
155→                  className={`flex items-center gap-1.5 text-xs ${ct.count > 0 ? "text-muted-foreground" : "text-muted-foreground/40"}`}
156→                >
157→                  <span
158→                    className="inline-block w-2 h-2 rounded-full shrink-0"
159→                    style={{ backgroundColor: ct.color, opacity: ct.count > 0 ? 1 : 0.3 }}
160→                  />
161→                  {ct.label} ({ct.count})
162→                </span>
163→              ))}
164→              {total === 0 && (
165→                <span className="flex items-center gap-1.5 text-xs text-destructive">
166→                  <AlertTriangle className="h-3 w-3" />
167→                  No credits remaining
168→                </span>
169→              )}
170→            </div>
171→
172→            {/* Active source note */}
173→            {activeSource && !showLegacy && (
174→              <p className="text-[11px] text-muted-foreground">
175→                Using {activeSource} credits first.{" "}
176→                {activeSource === "monthly" && "Top-up & bonus credits never expire."}
177→              </p>
178→            )}
179→          </div>
180→        </TooltipProvider>
181→
182→        {isLow && total > 0 && (
183→          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
184→            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
185→            Low credits — top up to keep ranking resumes.
186→          </div>
187→        )}
188→        {total === 0 && (
189→          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
190→            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
191→            No credits left — buy a pack or upgrade to continue ranking.
192→          </div>
193→        )}
194→      </CardContent>
195→    </Card>
196→  );
197→};
198→
199→export default AccountInfoCard;
200→

 1→import { useState, useCallback, useRef, useEffect, useMemo } from "react";
 2→import { useAuth } from "@/hooks/useAuth";
 3→import { usePlatformConfig } from "@/hooks/usePlatformConfig";
 4→import { validateRanking } from "@/lib/validateRanking";
 5→import { findDuplicateResumeIds } from "@/lib/deduplicateCandidates";
 6→import { supabase } from "@/integrations/supabase/client";
 7→import { Button } from "@/components/ui/button";
 8→import { Textarea } from "@/components/ui/textarea";
 9→import { Checkbox } from "@/components/ui/checkbox";
10→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
11→import { Badge } from "@/components/ui/badge";
12→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
13→import { Progress } from "@/components/ui/progress";
14→import {
15→  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
16→  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
17→} from "@/components/ui/alert-dialog";
18→import { toast } from "sonner";
19→import {
20→  Upload, Copy, Loader2, FileText,
21→  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
22→  Brain, ListChecks, BarChart2, ArrowRight, Sparkles, Clock, Users, Star, Mail, Zap,
23→  Archive, ArchiveRestore, FolderOpen, Wand2, Pencil
24→} from "lucide-react";
25→import { exportToCSV } from "@/lib/csvExport";
26→import CandidateRow from "@/components/CandidateRow";
27→import JDRewriteDialog from "@/components/JDRewriteDialog";
28→import ConfidenceReport from "@/components/ConfidenceReport";
29→import type { PastJob, Result, ExistingResume } from "@/pages/Index";
30→import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
31→
32→interface JobDetailViewProps {
33→  selectedJobId: string | null;
34→  selectedJob: PastJob | null;
35→  results: Result[];
36→  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
37→  existingResumes: ExistingResume[];
38→  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
39→  onJobCreated: (job: PastJob) => void;
40→  onAuthRequired: () => void;
41→  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
42→  isAuthenticated?: boolean;
43→}
44→
45→interface UploadedFile {
46→  file: File;
47→  name: string;
48→}
49→
50→const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
51→
52→const JobDetailView = ({
53→  selectedJobId,
54→  selectedJob,
55→  results,
56→  setResults,
57→  existingResumes,
58→  setExistingResumes,
59→  onJobCreated,
60→  onAuthRequired,
61→  onJobUpdated,
62→  isAuthenticated = true,
63→}: JobDetailViewProps) => {
64→  const { user, profile, refreshProfile } = useAuth();
