### Feature 2: Entrance Animations with framer-motion

#### 2A. Install framer-motion

**Command:** `npm install framer-motion`

This adds it to `dependencies` in `package.json`.

#### 2B. Create `FadeIn` wrapper component

**New file:** `/Users/yashbaldha/Desktop/Shopify App/Rankora/src/components/ui/fade-in.tsx`

```tsx
import { motion, type HTMLMotionProps } from "framer-motion";
import { forwardRef } from "react";

interface FadeInProps extends HTMLMotionProps<"div"> {
  /** Delay in seconds before animation starts */
  delay?: number;
  /** Duration in seconds */
  duration?: number;
  /** Direction to fade in from: "up", "down", "left", "right", or "none" */
  direction?: "up" | "down" | "left" | "right" | "none";
  /** Distance in pixels for the translate */
  distance?: number;
}

const directionMap = {
  up: { y: 1, x: 0 },
  down: { y: -1, x: 0 },
  left: { x: 1, y: 0 },
  right: { x: -1, y: 0 },
  none: { x: 0, y: 0 },
};

const FadeIn = forwardRef<HTMLDivElement, FadeInProps>(
  ({ delay = 0, duration = 0.2, direction = "up", distance = 10, children, ...props }, ref) => {
    const dir = directionMap[direction];
    return (
      <motion.div
        ref={ref}
        initial={{ opacity: 0, x: dir.x * distance, y: dir.y * distance }}
        animate={{ opacity: 1, x: 0, y: 0 }}
        transition={{ duration, delay, ease: "easeOut" }}
        {...props}
      >
        {children}
      </motion.div>
    );
  }
);
FadeIn.displayName = "FadeIn";

export { FadeIn };
```

framer-motion automatically respects `prefers-reduced-motion` via its `useReducedMotion` hook. Starting from framer-motion v10+, it automatically reduces animations when the user has enabled reduced motion in their OS settings. No extra code needed.

#### 2C. Create `StaggerList` wrapper component

**New file:** `/Users/yashbaldha/Desktop/Shopify App/Rankora/src/components/ui/stagger-list.tsx`

```tsx
import { motion, AnimatePresence } from "framer-motion";
import { Children, type ReactNode } from "react";

interface StaggerListProps {
  children: ReactNode;
  /** Stagger delay between children in seconds */
  stagger?: number;
  /** Duration for each child animation */
  duration?: number;
  /** Direction of fade */
  direction?: "up" | "down" | "left" | "right" | "none";
  /** Translate distance in pixels */
  distance?: number;
  /** Additional className for the container */
  className?: string;
  /** HTML tag for container, default "div" */
  as?: "div" | "ul" | "ol";
}

const directionMap = {
  up: { y: 1, x: 0 },
  down: { y: -1, x: 0 },
  left: { x: 1, y: 0 },
  right: { x: -1, y: 0 },
  none: { x: 0, y: 0 },
};

const containerVariants = (stagger: number) => ({
  hidden: {},
  visible: { transition: { staggerChildren: stagger } },
});

const itemVariants = (direction: string, distance: number, duration: number) => {
  const dir = directionMap[direction as keyof typeof directionMap] ?? directionMap.up;
  return {
    hidden: { opacity: 0, x: dir.x * distance, y: dir.y * distance },
    visible: { opacity: 1, x: 0, y: 0, transition: { duration, ease: "easeOut" } },
  };
};

const StaggerList = ({
  children,
  stagger = 0.05,
  duration = 0.2,
  direction = "up",
  distance = 10,
  className,
  as = "div",
}: StaggerListProps) => {
  const Tag = motion[as];
  return (
    <Tag
      className={className}
      variants={containerVariants(stagger)}
      initial="hidden"
      animate="visible"
    >
      {Children.map(children, (child) =>
        child ? (
          <motion.div variants={itemVariants(direction, distance, duration)}>
            {child}
          </motion.div>
        ) : null
      )}
    </Tag>
  );
};

export { StaggerList };
```

